import net.runelite.client.ui.components.materialtabs.MaterialTab;
import net.runelite.client.ui.components.materialtabs.MaterialTabGroup;

@Singleton
class BetterSkillCalculatorPanel extends PluginPanel
{
	private final BetterSkillCalculator uiCalculator;
	private final SkillIconManager iconManager;
	private final MaterialTabGroup tabGroup;

	private MaterialTab currentTab;
	private boolean shouldForceReload;

	@Inject
	BetterSkillCalculatorPanel(BetterSkillCalculator skillCalculator, SkillIconManager iconManager, UICalculatorInputArea uiInput, UICustomCalcSlot customSlot)
	{
		super();
		getScrollPane().setVerticalScrollBarPolicy(JScrollPane.VERTICAL_SCROLLBAR_ALWAYS);

		this.iconManager = iconManager;
		uiCalculator = skillCalculator;

		setBorder(new EmptyBorder(10, 10, 10, 10));
		setLayout(new GridBagLayout());

		GridBagConstraints c = new GridBagConstraints();
		c.fill = GridBagConstraints.HORIZONTAL;
		c.weightx = 1;
		c.gridx = 0;
		c.gridy = 0;

		tabGroup = new MaterialTabGroup();
		tabGroup.setLayout(new GridLayout(0, 6, 7, 7));

		addCalculatorButtons();

		uiInput.setBorder(new EmptyBorder(15, 0, 15, 0));
		uiInput.setBackground(ColorScheme.DARK_GRAY_COLOR);

		add(tabGroup, c);
		c.gridy++;

		add(uiInput, c);
		c.gridy++;

		// Custom rate sits above the action list so it's visible without scrolling.
		add(customSlot, c);
		c.gridy++;

		add(uiCalculator, c);
		c.gridy++;
	}

	private void addCalculatorButtons()
	{
		for (Skill skill : Skill.values())
		{
			if (skill == Skill.OVERALL)
			{
				continue;
			}

			final CalculatorType calculatorType = CalculatorType.getBySkill(skill);
			ImageIcon icon = new ImageIcon(iconManager.getSkillImage(skill, true));
			MaterialTab tab = new MaterialTab(icon, tabGroup, null);
			tab.setOnSelectEvent(() ->
			{
				uiCalculator.openCalculator(skill, calculatorType, shouldForceReload);
				currentTab = tab;
				shouldForceReload = false;
				return true;
			});

			tabGroup.addTab(tab);
		}
	}

	void reloadCurrentCalculator()
	{
		if (currentTab != null)
		{
			shouldForceReload = true;
			SwingUtilities.invokeLater(() -> tabGroup.select(currentTab));
		}
	}

}

